  carob: {"common": "carob", "latin": "Ceratonia siliqua", "form": "tree", "arch": "taproot", "h": 10, "spread": 10, "typ": 1.0, "max": 6.0, "lat": 8, "yrs": 15, "regen": "Drought-proof Mediterranean pod tree (food and fodder) whose deep roots ride out long dry spells; dense evergreen canopy is relatively fire-retardant. Not a nitrogen fixer.", "conf": "low", "note": "Sources describe roots as 'deep' and able to reach deep water layers but give no number; 6 m is an estimate (Canadell's mean for sclerophyllous trees is 12.6 m).", "src": [{"cite": "World Agroforestry, Agroforestree Database: Ceratonia siliqua (deep root system)", "url": "https://apps.worldagroforestry.org/treedb2/AFTPDFS/Ceratonia_siliqua.PDF"}, {"cite": "Canadell et al. 1996, Maximum rooting depth of vegetation types at the global scale (Oecologia 108:583-595), Appendix 1", "url": "https://jacksonlab.stanford.edu/sites/g/files/sbiybj20871/files/media/file/oecol96d.pdf"}]},
  mesquite: {"common": "honey mesquite", "latin": "Prosopis glandulosa", "form": "tree", "arch": "taproot", "h": 7, "spread": 9, "typ": 1.0, "max": 53.3, "lat": 15, "yrs": 15, "regen": "Nitrogen-fixing phreatophyte that taps deep groundwater, builds fertile 'islands' under its canopy, and feeds wildlife and people with sweet pods.", "conf": "high", "note": "53 m record is Phillips 1963, open-pit mine near Tucson (listed as P. juliflora, i.e. the mesquite complex). Species-specific P. glandulosa records: 15 m (Silva et al. 1989, NM), 20 m (Stromberg 2013). Laterals concentrate in top 0.3 m (Heitschmidt et al. 1988); 15 m lateral reach is an estimate.", "src": [{"cite": "Canadell et al. 1996, Maximum rooting depth of vegetation types at the global scale (Oecologia 108:583-595), Appendix 1", "url": "https://jacksonlab.stanford.edu/sites/g/files/sbiybj20871/files/media/file/oecol96d.pdf"}, {"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}, {"cite": "Meinzer 1927, Plants as indicators of ground water (USGS Water-Supply Paper 577)", "url": "https://pubs.usgs.gov/publication/wsp577"}]},
