  desertwillow: {"common": "desert willow", "latin": "Chilopsis linearis", "form": "tree", "arch": "taproot", "h": 6, "spread": 5, "typ": 0.8, "max": 1.6, "lat": 15, "yrs": 8, "regen": "Riparian-wash tree that stabilises sandy channels with far-reaching laterals and resprouts after fire or flood; hummingbird and bee magnet.", "conf": "medium", "note": "Documented max 1.6 m in a New Mexico arroyo excavation (Stromberg 2013 via TNC); FEIS rates rooting depth 'deep' with a taproot and horizontal roots to 15 m, so deeper roots are likely where groundwater is deeper.", "src": [{"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}, {"cite": "USDA FEIS species brief: Chilopsis linearis (taproot; horizontal roots to 15 m)", "url": "https://research.fs.usda.gov/feis/species-briefs/chilin"}]},
  lemon: {"common": "lemon", "latin": "Citrus limon", "form": "tree", "arch": "fibrous", "h": 5, "spread": 5, "typ": 0.75, "max": 3.3, "lat": 4, "yrs": 8, "regen": "Productive evergreen food tree; shallow fibrous roots need mulch and steady water, so it builds soil best inside a mulched, irrigated guild.", "conf": "medium", "note": "Main citrus roots in 0.6-0.9 m; 79% of fibrous roots in top 60 cm (Valencia on sand). Max 3.3 m recorded on rough lemon rootstock in deep Florida sand (Obreza & Boman, cited in review). Depth depends heavily on rootstock.", "src": [{"cite": "Advances in Horticultural Science review of citrus root distribution (Obreza & Boman 2002 data)", "url": "https://oaj.fupress.net/index.php/ahs/article/download/2937/2937"}, {"cite": "Allen et al. 1998, FAO-56 Crop Evapotranspiration, Table 22 max effective root depth", "url": "https://www.fao.org/4/x0490e/x0490e0e.htm"}]},
