  almond: {"common": "almond", "latin": "Prunus dulcis", "form": "tree", "arch": "heart", "h": 6, "spread": 6, "typ": 0.9, "max": 3.0, "lat": 5, "yrs": 8, "regen": "Early-spring bloom feeds bees when little else flowers; drought-adapted nut tree for dry orchards with cover crops between rows.", "conf": "low", "note": "CDFA almond study found large roots to 1.5 m (60 in) at low density; FAO model depth 1.0-2.0 m. Related Prunus persica recorded 4.7-4.9 m (Howard 1925, TNC). 3 m maximum is an estimate.", "src": [{"cite": "Brown et al., CDFA FREP final report 11-0461, almond root growth and N uptake", "url": "https://www.cdfa.ca.gov/is/ffldrs/frep/pdfs/CompletedProjects/11-0461-SABrown-SA112-115%20FR.pdf"}, {"cite": "Allen et al. 1998, FAO-56 Crop Evapotranspiration, Table 22 max effective root depth", "url": "https://www.fao.org/4/x0490e/x0490e0e.htm"}, {"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}]},
  jujube: {"common": "jujube", "latin": "Ziziphus jujuba", "form": "tree", "arch": "taproot", "h": 7, "spread": 5, "typ": 1.0, "max": 10.0, "lat": 4, "yrs": 10, "regen": "Very drought- and heat-tolerant fruit tree whose deep taproot keeps it alive on dry, alkaline, poor soils; suckers can fill in eroding ground.", "conf": "medium", "note": "10 m documented in rain-fed Loess Plateau plantations, Yulin, Shaanxi (Ma et al. 2013, 2014 via TNC); fine roots concentrate in top ~0.8 m in irrigated orchards (Xinjiang).", "src": [{"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}, {"cite": "Soil water and root patterns in rain-fed jujube plantations across stand ages, Loess Plateau", "url": "https://agris.fao.org/search/fr/records/65dfbc5e0f3e94b9e5dbd5d3"}]},
  moringa: {"common": "moringa", "latin": "Moringa oleifera", "form": "tree", "arch": "tuber", "h": 8, "spread": 4, "typ": 0.4, "max": 2.0, "lat": 2, "yrs": 3, "regen": "Fast pioneer tree with a swollen storage taproot; heavy coppiced leaf biomass for mulch and fodder; frost-tender in cold valleys.", "conf": "low", "note": "Seedling study (12 months, compacted clay): 90% of root volume within ~40 cm of the taproot; explored less deeply than castor. No mature-tree maximum found; 2 m is an estimate.", "src": [{"cite": "Univ. Sassari 2018 study of Moringa vs Ricinus root architecture in compacted clay", "url": "https://unifind.uniss.it/resource/item/102670"}]},
