  elder: {"common": "blue elderberry", "latin": "Sambucus nigra ssp. cerulea (S. mexicana)", "form": "shrub", "arch": "fibrous", "h": 5, "spread": 5, "typ": 0.5, "max": 3.0, "lat": 3, "yrs": 4, "regen": "Fast native riparian pioneer for hedgerows and bank planting; berries and flowers feed birds, pollinators and people; resprouts after fire.", "conf": "low", "note": "Only maximum found is 3 m from a horticulture book (Kourik 2015, in TNC database); extension sources describe shallow spreading roots mostly in top 0.3-0.5 m.", "src": [{"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}, {"cite": "USDA FEIS species review: Sambucus nigra ssp. cerulea", "url": "https://www.fs.usda.gov/database/feis/plants/shrub/samnigc/all.html"}]},
