  pricklypear: {"common": "prickly pear", "latin": "Opuntia ficus-indica", "form": "succulent", "arch": "succulentShallow", "h": 3, "spread": 3, "typ": 0.15, "max": 1.2, "lat": 2.5, "yrs": 3, "regen": "Living fence, firebreak and emergency fodder; shallow net roots grab light rain within hours ('rain roots'); pads root easily to green bare ground.", "conf": "medium", "note": "Field study (South Africa): most roots in top 10-15 cm; laterals 1.7 m after one season and 2.5 m after two; roots sampled to 1.2 m. Other Opuntia spp. 0.12-1.47 m (TNC).", "src": [{"cite": "Snyman, Root dynamics and water studies on Opuntia ficus-indica and O. robusta (Univ. Free State)", "url": "https://scholar.ufs.ac.za/items/e3bdfc0f-de55-454b-84e5-4ce15ad578f4"}, {"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}]},
