  ceanothus: {"common": "ceanothus (California lilac)", "latin": "Ceanothus spp. (e.g. C. leucodermis, C. spinosus)", "form": "shrub", "arch": "taproot", "h": 3, "spread": 3, "typ": 0.8, "max": 3.7, "lat": 2, "yrs": 5, "regen": "Native nitrogen-fixing chaparral shrub (Frankia root nodules) that rebuilds soil after fire and stabilises slopes; huge spring bee bloom.", "conf": "high", "note": "Chaparral excavations: C. leucodermis 3.7 m, C. spinosus 2.4-3.1 m, C. megacarpus 1.9-2.4 m, C. oliganthus 1.8 m (Hellmers et al. 1955; Thomas & Davis 1989). Species and substrate (fractured sandstone vs clay) matter.", "src": [{"cite": "Canadell et al. 1996, Maximum rooting depth of vegetation types at the global scale (Oecologia 108:583-595), Appendix 1", "url": "https://jacksonlab.stanford.edu/sites/g/files/sbiybj20871/files/media/file/oecol96d.pdf"}, {"cite": "The Nature Conservancy 2018, Plant Rooting Depth Database (compiled literature values)", "url": "https://groundwaterexchange.org/tool-post/gde-rooting-depths-database/"}]},
